class CoreTests {
 static int tests;
 static void Check(bool condition,string name){if(!condition)throw new Exception("FAIL: "+name);tests++;Console.WriteLine("PASS "+name);}
 static void Reject(Action action,string name){try{action();}catch(SafeError){Check(true,name);return;}throw new Exception("FAIL expected rejection: "+name);}
 static string Rss(string id="one",string title="文章标题"){return "<rss version='2.0' xmlns:content='http://purl.org/rss/1.0/modules/content/'><channel><title>来源名</title><item><guid>"+id+"</guid><title>"+title+"</title><link>https://example.com/article/"+id+"</link><pubDate>"+DateTime.UtcNow.ToString("r")+"</pubDate><content:encoded><![CDATA[<p>正文 <a href='/product'>商品链接</a><img src='https://example.com/photo.png'></p>]]></content:encoded></item></channel></rss>";}
 static int Main(){string folder=Path.Combine(Path.GetTempPath(),"ShixunTests-"+Guid.NewGuid().ToString("N"));try{
 Check(Transport.Decode(Encoding.UTF8.GetBytes("中文"),"text/xml")=="中文","UTF-8 feed without HTTP charset");
 Check(Transport.Decode(Encoding.GetEncoding("gb18030").GetBytes("<?xml version='1.0' encoding='gb18030'?><x>中文</x>"),"text/xml").Contains("中文"),"XML declaration charset respected");
 Check(Transport.Decode(Encoding.Unicode.GetPreamble().Concat(Encoding.Unicode.GetBytes("中文")).ToArray(),"text/xml")=="中文","UTF-16 BOM respected");
 var source=new Source{id="fixture",url="https://example.com/feed"};var feed=Feeds.Parse(Rss(),source,new Uri(source.url));Check(feed.articles[0].title=="文章标题"&&feed.title=="来源名","RSS content title independent of source");Check(feed.articles[0].html.Contains("商品链接")&&feed.articles[0].images.Count==1,"rich content and images retained");Check(Feeds.Parse(Rss("x","来源名"),source,new Uri(source.url)).articles[0].title.Contains("正文"),"source-title placeholder falls back to content");
 var atom=Feeds.Parse("<feed xmlns='http://www.w3.org/2005/Atom'><title>Atom源</title><entry><id>entry</id><title>Atom文章</title><link href='/atom'/><content type='html'>&lt;p&gt;Atom内容&lt;/p&gt;</content><updated>2026-11-12T02:00:00Z</updated></entry></feed>",source,new Uri(source.url));Check(atom.format=="Atom"&&atom.articles[0].link=="https://example.com/atom","Atom and relative URL");Reject(()=>Feeds.Parse("<!DOCTYPE rss [<!ENTITY x SYSTEM 'file:///secret'>]><rss><channel><title>&x;</title></channel></rss>",source,new Uri(source.url)),"DTD rejected");
 Check(Feeds.Discover("<html><link rel='alternate' type='application/atom+xml' href='/atom.xml'></html>",new Uri(source.url)).Single()=="https://example.com/atom.xml","website feed discovery");Check(Feeds.Parse("<rss><channel><title>x</title><item><guid>missingdate</guid><description>无标题正文</description></item></channel></rss>",source,new Uri(source.url)).articles[0].dateOrigin=="firstSeen","missing date explicitly firstSeen");
 var profile=new RequestProfile{mode="bearer",token="fixture-secret",fields=new List<RequestField>{new RequestField{place="query",name="key",value="a+b &c"},new RequestField{place="path",name="id",value="part/one"},new RequestField{place="header",name="X-Extra",value="second-secret"}}};string requestUrl=Transport.RequestUrl("https://example.com/{id}?existing=1",profile);Console.WriteLine("Fixture URL: "+requestUrl);Check(requestUrl.Contains("part%2Fone")&&requestUrl.Contains("key=a%2Bb%20%26c"),"multi-parameter path/query encoding");Reject(()=>Transport.ValidateUrl("https://user:password@example.com/feed"),"URL userinfo rejected");Reject(()=>Transport.ValidateProfile(new RequestProfile{fields=new List<RequestField>{new RequestField{place="header",name="X-Test",value="x\r\nX-Stolen: y"}}}),"header injection rejected");Reject(()=>Transport.ValidateProfile(new RequestProfile{fields=new List<RequestField>{new RequestField{place="header",name="Host",value="evil"}}}),"restricted headers rejected");Reject(()=>Transport.ValidateProfile(new RequestProfile{mode="bearer",fields=new List<RequestField>{new RequestField{place="header",name="Authorization",value="x"}}}),"ambiguous authentication rejected");Reject(()=>Transport.Fetch("http://example.com/feed",profile),"credentials require HTTPS");
 Check(Transport.FeedUpdated("2026-11-12T05:50:43.554Z")>0&&Transport.FeedUpdated("invalid")==0,"optional upstream cache timestamp parsing");var state=new ClientState();Check(state.sources.Count==0&&state.settings.notifyScope=="all"&&state.settings.confirmDelete,"empty sources, all notifications, delete confirmation defaults");state.categories.Add(new Category{id="c",name="技术",keywords="开源",exclude="广告"});var article=new Article{title="开源工具",summary="",category=""};Check(Rules.Classify(state,article)=="c","custom classification");article.locked=true;article.category="manual";Check(Rules.Classify(state,article)=="manual","manual category lock");state.settings.notifyScope="filtered";state.settings.notifyKeywords="开源";Check(Rules.Notify(state.settings,article),"keyword notification filter");state.settings.notifyKeywords="";state.settings.notifyCategories.Add("manual");Check(Rules.Notify(state.settings,article),"category notification filter");state.settings.notifyKeywords="不匹配";state.settings.notifyJoin="all";Check(!Rules.Notify(state.settings,article),"notification AND semantics");state.settings.notifyKeywords="";state.settings.notifyCategories.Clear();Check(!Rules.Notify(state.settings,article),"empty filtered selection suppresses notifications");Check(Rules.Quiet(new Preferences(),new DateTime(2026,11,12,23,0,0))&&!Rules.Quiet(new Preferences(),new DateTime(2026,11,12,12,0,0)),"overnight quiet hours");
 var rule=Rules.Parse("{\"version\":1,\"categories\":[{\"key\":\"tech\",\"name\":\"远程技术\",\"color\":\"#729178\",\"keywords\":[\"开源\"],\"exclude\":[]}]}");Rules.Apply(state,rule,"owner1");Rules.Apply(state,rule,"owner1");Check(state.categories.Count==2,"rule updates retain stable owner/key");Rules.Apply(state,rule,"owner2");Check(state.categories.Count==3,"separate rule sources do not overwrite each other");Reject(()=>Rules.Parse("{\"version\":7,\"categories\":[]}"),"invalid rule schema rejected");
 var store=new Store(folder);store.State.credentials["x"]=profile;store.Save();Check(!Encoding.UTF8.GetString(File.ReadAllBytes(Path.Combine(folder,"state.dpapi"))).Contains("fixture-secret"),"DPAPI ciphertext does not expose secrets");Check(new Store(folder).State.credentials["x"].token=="fixture-secret","DPAPI credentials round trip");store.State.articles.Add(new Article{id="old",time=Data.Now()-2*86400000d});store.State.articles.Add(new Article{id="recent",time=Data.Now()});store.State.deleted.Add(new Mark{id="removed",time=Data.Now()});store.Clean();Check(store.State.articles.Count==1&&store.State.articles[0].id=="recent"&&store.State.deleted.Count==1,"one-day cleanup keeps ID tombstones");
 using(var server=new FixtureServer()){
 var fetched=Transport.Fetch(server.Url+"auth",new RequestProfile{mode="bearer",token="fixture-token",fields=new List<RequestField>{new RequestField{place="header",name="X-Extra",value="two"},new RequestField{place="query",name="api_key",value="three"}}});Check(fetched.upstreamUpdated>0,"real response retains upstream cache timestamp");Check(fetched.status==200&&server.Last.Contains("Authorization: Bearer fixture-token")&&server.Last.Contains("X-Extra: two")&&server.Last.Contains("api_key=three"),"real request sends independent multiple auth parameters");
 Transport.Fetch(server.Url+"post",new RequestProfile{method="POST",fields=new List<RequestField>{new RequestField{place="form",name="token",value="form+value"}}});Check(server.Last.Contains("token=form%2Bvalue")&&server.Last.StartsWith("POST"),"POST form encoding");Transport.Fetch(server.Url+"json",new RequestProfile{method="POST",body="{\"token\":\"json-token\"}"});Check(server.Last.Contains("json-token"),"POST JSON body");Reject(()=>Transport.Fetch(server.Url+"redirect",new RequestProfile{mode="bearer",token="fixture"}),"authenticated cross-origin redirect blocked");Reject(()=>Transport.Fetch(server.Url+"limit",null),"HTTP rate limit handled");
 var s=new Source{name="本地测试",url=server.Url+"feed",id="engine-source"};store.State.sources.Add(s);var engine=new Engine(store);int notices=0;engine.Arrived+=items=>notices+=items.Count;store.State.settings.notifyScope="all";engine.Run(true).Wait();Check(s.initialized&&notices==0,"first sync creates baseline without notifications");engine.Run(true).Wait();Check(store.State.articles.Count(a=>a.source==s.id)==1&&notices==0,"same post deduplicates without repeat notification");server.NewId="two";engine.Run(true).Wait();Check(notices==1,"new article notifies exactly once");var newArticle=store.State.articles.First(a=>a.source==s.id&&a.guid=="two");store.State.deleted.Add(new Mark{id=newArticle.id,time=Data.Now()});store.State.articles.Remove(newArticle);engine.Run(true).Wait();Check(!store.State.articles.Any(a=>a.id==newArticle.id)&&notices==1,"deleted post does not resurrect or renotify");Check(!engine.HasDue(),"scheduler honors next-run time");s.enabled=false;server.NewId="paused-post";engine.Run(true).Wait();Check(!store.State.articles.Any(a=>a.guid=="paused-post"),"paused source is skipped even during manual sync");s.enabled=true;s.nextRun=0;engine.Run().Wait();Check(store.State.articles.Any(a=>a.guid=="paused-post"),"resumed source can sync immediately");
 var rs=new RuleSource{name="private rules",url=server.Url+"rules",id="private-rules"};store.State.ruleSources.Add(rs);store.State.credentials[rs.id]=new RequestProfile{mode="basic",username="reader",password="secret"};var preview=engine.UpdateRules(rs.id,false);Check(preview.categories.Count==1&&server.Last.Contains("Authorization: Basic "),"private rule sources use independent authentication");Check(!store.State.categories.Any(c=>c.ruleSource==rs.id),"remote check does not silently apply rules");
 }
 int imageRequests=0;Func<Task<byte[]>> imageFetch=async()=>{Interlocked.Increment(ref imageRequests);await Task.Delay(60);return new byte[]{1,2,3};};var imageTasks=Enumerable.Range(0,12).Select(i=>ImageCache.Get("same",imageFetch)).ToArray();Task.WaitAll(imageTasks);Check(imageRequests==1,"concurrent duplicate images coalesce");ImageCache.Get("same",imageFetch).Wait();Check(imageRequests==1,"short-lived image memory cache avoids repeated requests");
 var batchState=new ClientState();batchState.categories.Add(new Category{id="cat",name="分类"});batchState.articles.Add(new Article{id="one"});batchState.articles.Add(new Article{id="two"});batchState.articles.Add(new Article{id="outside"});var picks=BatchEdit.Resolve(batchState,new List<string>{"one","one","two","missing"},"read","");Check(picks.Count==2,"batch deduplicates IDs and skips expired rows");BatchEdit.Apply(batchState,picks,"read","");Check(picks.All(a=>a.read)&&!batchState.articles.Last().read,"batch only affects selected articles");BatchEdit.Apply(batchState,picks,"star","");BatchEdit.Apply(batchState,picks,"star","");Check(picks.All(a=>a.star),"batch star is idempotent");BatchEdit.Apply(batchState,picks,"unstar","");Check(picks.All(a=>!a.star),"batch unstar");BatchEdit.Apply(batchState,picks,"classify","cat");Check(picks.All(a=>a.locked&&a.category=="cat"),"batch category locks manual choices");Reject(()=>BatchEdit.Resolve(batchState,new List<string>{"one"},"classify","bad"),"batch validates category before modifying");Reject(()=>BatchEdit.Resolve(batchState,new List<string>{"one"},"unknown",""),"batch rejects invalid operation");Reject(()=>BatchEdit.Resolve(batchState,new List<string>(),"read",""),"batch rejects empty selection");var backup=picks.Select(Data.Clone).ToList();BatchEdit.Apply(batchState,picks,"delete","");Check(batchState.articles.Count==1&&batchState.deleted.Count==2,"batch delete records tombstones");Check(BatchEdit.Restore(batchState,backup)==2&&batchState.deleted.Count==0&&BatchEdit.Restore(batchState,backup)==0,"batch undo restores without duplicates");
 Console.WriteLine("RESULT: "+tests+" passed");return 0;
 }catch(Exception ex){Console.Error.WriteLine(ex.ToString());return 1;}finally{if(Directory.Exists(folder))Directory.Delete(folder,true);}}
 sealed class FixtureServer:IDisposable {
  readonly TcpListener listener;readonly Task worker;volatile bool stopped;public string Last="",NewId="one";public readonly string Url;
  public FixtureServer(){listener=new TcpListener(IPAddress.Loopback,0);listener.Start();Url="http://127.0.0.1:"+((IPEndPoint)listener.LocalEndpoint).Port+"/";worker=Task.Run(()=>{while(!stopped){try{using(var client=listener.AcceptTcpClient()){client.ReceiveTimeout=3000;using(var stream=client.GetStream()){var bytes=new List<byte>();int value;while((value=stream.ReadByte())>=0){bytes.Add((byte)value);int n=bytes.Count;if(n>=4&&bytes[n-4]==13&&bytes[n-3]==10&&bytes[n-2]==13&&bytes[n-1]==10)break;if(n>100000)break;}string headers=Encoding.UTF8.GetString(bytes.ToArray());int length=0;foreach(var line in headers.Split('\n'))if(line.StartsWith("Content-Length:",StringComparison.OrdinalIgnoreCase))int.TryParse(line.Substring(15).Trim(),out length);var body=new byte[length];int read=0;while(read<length){int count=stream.Read(body,read,length-read);if(count<=0)break;read+=count;}Last=headers+Encoding.UTF8.GetString(body);string route=headers.Split(' ')[1],text=route.StartsWith("/rules")?"{\"version\":1,\"categories\":[{\"key\":\"tech\",\"name\":\"私有规则\",\"color\":\"#729178\",\"keywords\":[\"开源\"],\"exclude\":[]}]}":Rss(NewId);string status=route.StartsWith("/redirect")?"302 Found":route.StartsWith("/limit")?"429 Too Many Requests":"200 OK";var content=Encoding.UTF8.GetBytes(text);var response=Encoding.ASCII.GetBytes("HTTP/1.1 "+status+"\r\nContent-Type: application/xml; charset=utf-8\r\nX-Feed-Updated-At: 2026-11-12T05:50:43.554Z\r\nContent-Length: "+content.Length+"\r\nConnection: close\r\n"+(route.StartsWith("/redirect")?"Location: http://localhost:1/stolen\r\n":"")+(route.StartsWith("/limit")?"Retry-After: 12\r\n":"")+"\r\n");stream.Write(response,0,response.Length);stream.Write(content,0,content.Length);}}}catch{if(stopped)break;}}});}
  public void Dispose(){stopped=true;listener.Stop();worker.Wait(3000);}
 }
